mkitem!{# [doc = " Raw file descriptors."] # [stable (feature = "rust1" , since = "1.0.0")] # [cfg (not (target_os = "hermit"))] pub type RawFd = raw :: c_int ;}
mkitem!{# [stable (feature = "rust1" , since = "1.0.0")] # [cfg (target_os = "hermit")] pub type RawFd = i32 ;}
mkitem!{mktrait!{# [doc = " A trait to extract the raw file descriptor from an underlying object."] # [doc = ""] # [doc = " This is only available on unix and WASI platforms and must be imported in"] # [doc = " order to call the method. Windows platforms have a corresponding"] # [doc = " `AsRawHandle` and `AsRawSocket` set of traits."] # [stable (feature = "rust1" , since = "1.0.0")] pub trait AsRawFd { # [doc = " Extracts the raw file descriptor."] # [doc = ""] # [doc = " This function is typically used to **borrow** an owned file descriptor."] # [doc = " When used in this way, this method does **not** pass ownership of the"] # [doc = " raw file descriptor to the caller, and the file descriptor is only"] # [doc = " guaranteed to be valid while the original object has not yet been"] # [doc = " destroyed."] # [doc = ""] # [doc = " However, borrowing is not strictly required. See [`AsFd::as_fd`]"] # [doc = " for an API which strictly borrows a file descriptor."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::File;"] # [doc = " # use std::io;"] # [doc = " #[cfg(any(unix, target_os = \"wasi\"))]"] # [doc = " use std::os::fd::{AsRawFd, RawFd};"] # [doc = ""] # [doc = " let mut f = File::open(\"foo.txt\")?;"] # [doc = " // Note that `raw_fd` is only valid as long as `f` exists."] # [doc = " #[cfg(any(unix, target_os = \"wasi\"))]"] # [doc = " let raw_fd: RawFd = f.as_raw_fd();"] # [doc = " # Ok::<(), io::Error>(())"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] fn as_raw_fd (& self) -> RawFd ; }}}
mkitem!{mktrait!{# [doc = " A trait to express the ability to construct an object from a raw file"] # [doc = " descriptor."] # [stable (feature = "from_raw_os" , since = "1.1.0")] pub trait FromRawFd { # [doc = " Constructs a new instance of `Self` from the given raw file"] # [doc = " descriptor."] # [doc = ""] # [doc = " This function is typically used to **consume ownership** of the"] # [doc = " specified file descriptor. When used in this way, the returned object"] # [doc = " will take responsibility for closing it when the object goes out of"] # [doc = " scope."] # [doc = ""] # [doc = " However, consuming ownership is not strictly required. Use a"] # [doc = " [`From<OwnedFd>::from`] implementation for an API which strictly"] # [doc = " consumes ownership."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The `fd` passed in must be an [owned file descriptor][io-safety];"] # [doc = " in particular, it must be open."] # [doc = ""] # [doc = " [io-safety]: io#io-safety"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::File;"] # [doc = " # use std::io;"] # [doc = " #[cfg(any(unix, target_os = \"wasi\"))]"] # [doc = " use std::os::fd::{FromRawFd, IntoRawFd, RawFd};"] # [doc = ""] # [doc = " let f = File::open(\"foo.txt\")?;"] # [doc = " # #[cfg(any(unix, target_os = \"wasi\"))]"] # [doc = " let raw_fd: RawFd = f.into_raw_fd();"] # [doc = " // SAFETY: no other functions should call `from_raw_fd`, so there"] # [doc = " // is only one owner for the file descriptor."] # [doc = " # #[cfg(any(unix, target_os = \"wasi\"))]"] # [doc = " let f = unsafe { File::from_raw_fd(raw_fd) };"] # [doc = " # Ok::<(), io::Error>(())"] # [doc = " ```"] # [stable (feature = "from_raw_os" , since = "1.1.0")] unsafe fn from_raw_fd (fd : RawFd) -> Self ; }}}
mkitem!{mktrait!{# [doc = " A trait to express the ability to consume an object and acquire ownership of"] # [doc = " its raw file descriptor."] # [stable (feature = "into_raw_os" , since = "1.4.0")] pub trait IntoRawFd { # [doc = " Consumes this object, returning the raw underlying file descriptor."] # [doc = ""] # [doc = " This function is typically used to **transfer ownership** of the underlying"] # [doc = " file descriptor to the caller. When used in this way, callers are then the unique"] # [doc = " owners of the file descriptor and must close it once it's no longer needed."] # [doc = ""] # [doc = " However, transferring ownership is not strictly required. Use a"] # [doc = " [`Into<OwnedFd>::into`] implementation for an API which strictly"] # [doc = " transfers ownership."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::File;"] # [doc = " # use std::io;"] # [doc = " #[cfg(any(unix, target_os = \"wasi\"))]"] # [doc = " use std::os::fd::{IntoRawFd, RawFd};"] # [doc = ""] # [doc = " let f = File::open(\"foo.txt\")?;"] # [doc = " #[cfg(any(unix, target_os = \"wasi\"))]"] # [doc = " let raw_fd: RawFd = f.into_raw_fd();"] # [doc = " # Ok::<(), io::Error>(())"] # [doc = " ```"] # [must_use = "losing the raw file descriptor may leak resources"] # [stable (feature = "into_raw_os" , since = "1.4.0")] fn into_raw_fd (self) -> RawFd ; }}}
mkitem!{mkimpl!{# [stable (feature = "raw_fd_reflexive_traits" , since = "1.48.0")] impl AsRawFd for RawFd { # [inline] fn as_raw_fd (& self) -> RawFd { * self } }}}
mkitem!{mkimpl!{# [stable (feature = "raw_fd_reflexive_traits" , since = "1.48.0")] impl IntoRawFd for RawFd { # [inline] fn into_raw_fd (self) -> RawFd { self } }}}
mkitem!{mkimpl!{# [stable (feature = "raw_fd_reflexive_traits" , since = "1.48.0")] impl FromRawFd for RawFd { # [inline] unsafe fn from_raw_fd (fd : RawFd) -> RawFd { fd } }}}
mkitem!{mkimpl!{# [stable (feature = "rust1" , since = "1.0.0")] # [cfg (not (target_os = "trusty"))] impl AsRawFd for fs :: File { # [inline] fn as_raw_fd (& self) -> RawFd { self . as_inner () . as_raw_fd () } }}}
mkitem!{mkimpl!{# [stable (feature = "from_raw_os" , since = "1.1.0")] # [cfg (not (target_os = "trusty"))] impl FromRawFd for fs :: File { # [inline] unsafe fn from_raw_fd (fd : RawFd) -> fs :: File { unsafe { fs :: File :: from (OwnedFd :: from_raw_fd (fd)) } } }}}
mkitem!{mkimpl!{# [stable (feature = "into_raw_os" , since = "1.4.0")] # [cfg (not (target_os = "trusty"))] impl IntoRawFd for fs :: File { # [inline] fn into_raw_fd (self) -> RawFd { self . into_inner () . into_inner () . into_raw_fd () } }}}
