mkitem!{mkimpl!{# [stable (feature = "asraw_stdio_locks" , since = "1.35.0")] impl < 'a > AsRawFd for io :: StdoutLock < 'a > { # [inline] fn as_raw_fd (& self) -> RawFd { libc :: STDOUT_FILENO } }}}
mkitem!{mkimpl!{# [stable (feature = "asraw_stdio_locks" , since = "1.35.0")] impl < 'a > AsRawFd for io :: StderrLock < 'a > { # [inline] fn as_raw_fd (& self) -> RawFd { libc :: STDERR_FILENO } }}}
mkitem!{mkimpl!{# [doc = " This impl allows implementing traits that require `AsRawFd` on Arc."] # [doc = " ```"] # [doc = " # #[cfg(any(unix, target_os = \"wasi\"))] mod group_cfg {"] # [doc = " # #[cfg(target_os = \"wasi\")]"] # [doc = " # use std::os::wasi::io::AsRawFd;"] # [doc = " # #[cfg(unix)]"] # [doc = " # use std::os::unix::io::AsRawFd;"] # [doc = " use std::net::UdpSocket;"] # [doc = " use std::sync::Arc;"] # [doc = " trait MyTrait: AsRawFd {"] # [doc = " }"] # [doc = " impl MyTrait for Arc<UdpSocket> {}"] # [doc = " impl MyTrait for Box<UdpSocket> {}"] # [doc = " # }"] # [doc = " ```"] # [stable (feature = "asrawfd_ptrs" , since = "1.63.0")] impl < T : AsRawFd > AsRawFd for crate :: sync :: Arc < T > { # [inline] fn as_raw_fd (& self) -> RawFd { (* * self) . as_raw_fd () } }}}
mkitem!{mkimpl!{# [stable (feature = "asfd_rc" , since = "1.69.0")] impl < T : AsRawFd > AsRawFd for crate :: rc :: Rc < T > { # [inline] fn as_raw_fd (& self) -> RawFd { (* * self) . as_raw_fd () } }}}
mkitem!{mkimpl!{# [unstable (feature = "unique_rc_arc" , issue = "112566")] impl < T : AsRawFd + ? Sized > AsRawFd for crate :: rc :: UniqueRc < T > { # [inline] fn as_raw_fd (& self) -> RawFd { (* * self) . as_raw_fd () } }}}
mkitem!{mkimpl!{# [stable (feature = "asrawfd_ptrs" , since = "1.63.0")] impl < T : AsRawFd > AsRawFd for Box < T > { # [inline] fn as_raw_fd (& self) -> RawFd { (* * self) . as_raw_fd () } }}}
mkitem!{mkimpl!{# [stable (feature = "anonymous_pipe" , since = "1.87.0")] # [cfg (not (target_os = "trusty"))] impl AsRawFd for io :: PipeReader { fn as_raw_fd (& self) -> RawFd { self . 0 . as_raw_fd () } }}}
mkitem!{mkimpl!{# [stable (feature = "anonymous_pipe" , since = "1.87.0")] # [cfg (not (target_os = "trusty"))] impl FromRawFd for io :: PipeReader { unsafe fn from_raw_fd (raw_fd : RawFd) -> Self { Self :: from_inner (unsafe { FromRawFd :: from_raw_fd (raw_fd) }) } }}}
